The traditional view of scientific discovery is that breakthroughs happen when a single great mind has sudden 37Drop answer here . Although this can occur, it is not often the case. Advances are more likely to be the result of a longer process. In some cases, this process involves 38Drop answer here, such as Nicholson’s theory about proto-elements. In others, simple necessity may provoke innovation, as with Westrope’s decision to modify the position of his riding stirrups. There is also often an element of 39Drop answer here, for example, the coincidence of ideas that led to the invention of the Post-It note. With both the Law of Natural Selection and the Law of Effect, there may be no clear 40Drop answer here involved, but merely a process of variation and selection.
 
                                                
