The ‘algorithmication’ of jobs
Stella Pachidi of Cambridge Judge Business School has been focusing on the ‘algorithmication’ of jobs which rely not on production but on 31Drop answer here.
While monitoring a telecommunications company, Pachidi observed a growing 32Drop answer here on the recommendations made by AI, as workers begin to learn through the ‘algorithm’s eyes’. Meanwhile, staff are deterred from experimenting and using their own 33Drop answer here, and are therefore prevented from achieving innovation.
To avoid the kind of situations which Pachidi observed, researchers are trying to make AI’s decision-making process easier to comprehend, and to increase users’ 34Drop answer here with regard to the technology.
                                                
