INSERT INTO reading_questions (id, group_id, question_number, prompt, answer_key, explanation, points, metadata) VALUES ('00dab352-2928-4116-8bfc-584ecb2e7a4a', '004a26a6-b015-40cc-b034-67850e49ae9d', 2, 'ABCDE18 A move away from the exploration of heavily mined reserves on land is a good idea.
