INSERT INTO reading_questions (id, group_id, question_number, prompt, answer_key, explanation, points, metadata) VALUES ('14806e80-bd40-4d01-b0ff-ac0f09b87458', '943dd6be-4bf8-44c2-8892-06a78bbcaec5', 3, '25 26 Which TWO of the following statements does the writer make about the Viking Age?
