INSERT INTO reading_questions (id, group_id, question_number, prompt, answer_key, explanation, points, metadata) VALUES ('45e91e19-a146-4609-93f6-489a57a94ea9', 'f62a9482-3b27-4c66-a5c6-d60bb11aab7a', 1, 'ABC27 For our own safety, humans will need to restrict the abilities of robots.
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        28 The risk of robots harming us is less serious than humans believe it to be.
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        29 It will take many decades for robot intelligence to be as imaginative as human intelligence.
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        30 We may have to start considering whether we are treating robots fairly.
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        31 Robots are probably of more help to us on Earth than in space.
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        32 The ideas in high-quality science fiction may prove to be just as accurate as those found in the work of mediocre scientists.
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        33 There are those who look forward to robots developing greater intelligence.', NULL, NULL, 1, '{"options":[]}') ON CONFLICT (id) DO UPDATE SET prompt=EXCLUDED.prompt, metadata=EXCLUDED.metadata;
